import {describe,expect,it} from "vitest";
import {acquireFormalAdvisoryLock} from "../../src/crawler/formalAdvisoryLock";
function coordinator(){let held=false;const events:string[]=[];return{events,factory:()=>({connect:async()=>{events.push("connect")},query:async(text:string)=>{if(text.includes("try_advisory")){const acquired=!held;if(acquired)held=true;events.push(`acquire:${acquired}`);return{rows:[{acquired}]};}held=false;events.push("unlock");return{rows:[{unlocked:true}]};},end:async()=>{events.push("end")}})}}
describe("formal PostgreSQL advisory lock",()=>{
  it("makes an old holder reject recovery and a recovery holder reject crawler",async()=>{const shared=coordinator();const old=await acquireFormalAdvisoryLock({databaseUrl:"postgres://test",clientFactory:shared.factory as never});await expect(acquireFormalAdvisoryLock({databaseUrl:"postgres://test",clientFactory:shared.factory as never})).rejects.toThrow(/acquisition failed/i);await old.release();const recovery=await acquireFormalAdvisoryLock({databaseUrl:"postgres://test",clientFactory:shared.factory as never});await expect(acquireFormalAdvisoryLock({databaseUrl:"postgres://test",clientFactory:shared.factory as never})).rejects.toThrow();await recovery.release();});
  it("releases and closes on success and caller failure",async()=>{const shared=coordinator();const lock=await acquireFormalAdvisoryLock({databaseUrl:"postgres://test",clientFactory:shared.factory as never});try{throw new Error("crawl failure")}catch{}finally{await lock.release()}expect(shared.events).toEqual(expect.arrayContaining(["unlock","end"]));const next=await acquireFormalAdvisoryLock({databaseUrl:"postgres://test",clientFactory:shared.factory as never});await next.release();});
  it("fails closed and closes on database lock errors",async()=>{let ended=false;await expect(acquireFormalAdvisoryLock({databaseUrl:"postgres://test",clientFactory:()=>({connect:async()=>{},query:async()=>{throw new Error("db offline")},end:async()=>{ended=true}}) as never})).rejects.toThrow(/acquisition failed/i);expect(ended).toBe(true);});
  it("attempts end after unlock failure and aggregates unlock plus end failure",async()=>{let ended=false;const lock=await acquireFormalAdvisoryLock({databaseUrl:"postgres://test",clientFactory:()=>({connect:async()=>{},query:async(text:string)=>text.includes("try_")?{rows:[{acquired:true}]}:Promise.reject(new Error("unlock failed")),end:async()=>{ended=true;throw new Error("end failed")}}) as never});await expect(lock.release()).rejects.toSatisfy((error:AggregateError)=>error instanceof AggregateError&&error.errors.length===2);expect(ended).toBe(true);});
  it("aggregates acquisition and cleanup-end failures, including bounded timeouts",async()=>{await expect(acquireFormalAdvisoryLock({databaseUrl:"postgres://test",timeoutMs:5,clientFactory:()=>({connect:async()=>{},query:async()=>new Promise(()=>{}),end:async()=>{throw new Error("end failed")}}) as never})).rejects.toSatisfy((error:AggregateError)=>error instanceof AggregateError&&error.errors.length===2);});
});
